"use strict";
(() => {
 const version='0.5.11';document.querySelector('.version').textContent='v'+version;
 const notice=document.createElement('p');notice.className='notice';notice.textContent='This app automatically uses Google Gemini to check entry wording, classify call reasons and prepare weekly handovers. Problem/Resolution notes, including names and other details typed in them, are sent to Google when processing is needed. Continuing to use the app means accepting this processing. Suggestions never change your notes without approval.';const link=document.createElement('a');link.href='privacy.html';link.textContent=' Privacy details';notice.append(link);document.querySelector('header').after(notice);
 const stamp=new URL(location.href).searchParams.get('_refresh'),key=version+(stamp?'-'+stamp:'');document.querySelector('link[rel="stylesheet"]').href='styles.css?v='+encodeURIComponent(key);
 document.getElementById('refresh').addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();const open=['startPage','finishPage','editPage'].some(id=>!document.getElementById(id).classList.contains('hidden'));if(open&&!confirm('Reload? Unsaved form changes will be lost. Saved entries and running calls will be kept.'))return;const url=new URL(location.href);url.searchParams.set('_refresh',Date.now().toString());location.replace(url.href);},true);
 const load=path=>new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=path+'?v='+encodeURIComponent(key);script.onload=resolve;script.onerror=()=>reject(new Error('Could not load '+path+'. Check your connection and refresh.'));document.body.append(script);});
 localStorage.setItem('oncall.aiConsent.v1','yes');
 load('app.js').then(()=>load('drive-fix.js')).then(()=>load('ai-summaries.js')).then(()=>{const input=document.getElementById('aiConsent');input.checked=true;input.closest('label').style.display='none';return load('call-reasons.js');}).then(()=>load('language-review.js')).then(()=>{document.querySelector('.version').textContent='v'+version;}).catch(error=>{const box=document.getElementById('error');box.textContent=error.message;box.classList.remove('hidden');});
})();
